#!/usr/bin/env python3
"""
Homicide worldwide, second patch (culprits), 17 October 2026. Needs the first
homicide patch (homicide_culprits.py, already applied on main).

Stand-your-ground law becomes a row of its own beside the homicide map; the
homicide row's name and note no longer list animal sacrifice, animal fighting
or self-defense law.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTE = "## Homicide worldwide, second patch (17 October, a separate chat)\n\nNeeds the first homicide patch (guards on its heading). Not a numbered round;\nthis note goes at the end of this file. Two map files go into the maps repo by\nhand. No tiles patch. No app.js?v= bump.\n\n- Owner, 17 October: animal sacrifice and animal fighting have their own maps\n  and rows (site_animal_sacrifice, site_animal_fighting), so they are off the\n  homicide map; and stand-your-ground law is a map of its own.\n- maps repo: homicide.html replaced (4 parts now: homicide by country, cult-\n  related homicides, organized crime groups, gang territories; extract 5,354\n  features, 4 overlays). New stand_your_ground.html (Leaflet, L.polygon per\n  jurisdiction, each kind a layerGroup in L.control.layers): 56 US states and\n  territories in 7 kinds as Wikipedia's article and map classify them, and the\n  9 other jurisdictions it covers drawn as shapes (Alberta's box carries\n  Canada's text too); extract 65 features, 8 overlays.\n- registry.json: stand_your_ground (url = maps/main/stand_your_ground.html);\n  homicide_worldwide's name shortened to match.\n- app.js: homicide_worldwide's name, short name and note say what the map now\n  holds. New row stand_your_ground in SITE_MAPS (route sitemap, keepColour),\n  SHORT_NAMES, LAYER_KIND (human, downstream), LAYER_SITE, NOT_LIVE; in\n  PANEL_ORDER straight after homicide_worldwide, under Destruction > Of\n  individuals > Of humans.\n- test.mjs: one block, \"stand your ground (17 October)\"; round 102b's check\n  allows the line \"homicide_worldwide\", \"stand_your_ground\".\n"

DIFF = ""

FILES = ["map/app.js", "map/test.mjs", "pipeline/sitemaps/registry.json"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("homicide2: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Homicide worldwide (17 October" not in h.read_text(encoding="utf-8"):
        sys.exit("homicide2: the first homicide patch must be applied first (homicide_culprits.py)")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("homicide2: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", *FILES, check=False)
            sys.exit("homicide2: the diff did not apply:\n" + r.stdout + r.stderr)
        print("homicide2: applied")
    text = h.read_text(encoding="utf-8")
    if NOTE.split("\n", 1)[0] not in text:
        h.write_text(text.rstrip("\n") + "\n\n\n" + NOTE, encoding="utf-8")


if __name__ == "__main__":
    main()
